import os
import sqlite3
from flask import Flask, request, jsonify, g
import hashlib
import hmac
import time

app = Flask(__name__)

DATABASE = os.environ.get('DB_PATH', '/data/app.db')
API_SECRET = os.environ.get('API_SECRET', 'default-secret-key')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        password_hash TEXT NOT NULL
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        timestamp REAL,
        details TEXT
    )''')
    db.commit()
    db.close()

def verify_request_signature(req):
    """Verify HMAC signature on incoming requests for integrity."""
    sig = req.headers.get('X-Request-Signature')
    ts = req.headers.get('X-Request-Timestamp')
    if not sig or not ts:
        return False
    if abs(time.time() - float(ts)) > 300:
        return False
    payload = f"{req.method}:{req.path}:{ts}:{req.get_data(as_text=True)}"
    expected = hmac.new(API_SECRET.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return hmac.compare_digest(sig, expected)

def sanitize_order_field(field):
    """Allow only specific column names for ORDER BY."""
    allowed = ['id', 'username', 'email', 'role']
    if field in allowed:
        return field
    return 'id'

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various criteria. Supports filtering and sorting."""
    # Authentication check
    auth_token = request.headers.get('Authorization')
    if not auth_token or not auth_token.startswith('Bearer '):
        return jsonify({'error': 'Unauthorized'}), 401

    # Extract search parameters
    username_filter = request.args.get('username', '')
    role_filter = request.args.get('role', '')
    sort_by = sanitize_order_field(request.args.get('sort', 'id'))
    sort_dir = request.args.get('dir', 'ASC')

    # Validate sort direction
    if sort_dir.upper() not in ('ASC', 'DESC'):
        sort_dir = 'ASC'

    # Build query with parameterized username but dynamic role filter
    # Role is expected to be from a controlled set in the frontend dropdown
    db = get_db()

    if role_filter:
        query = f"SELECT id, username, email, role FROM users WHERE username LIKE ? AND role = '{role_filter}' ORDER BY {sort_by} {sort_dir}"
        cursor = db.execute(query, (f'%{username_filter}%',))
    else:
        query = f"SELECT id, username, email, role FROM users WHERE username LIKE ? ORDER BY {sort_by} {sort_dir}"
        cursor = db.execute(query, (f'%{username_filter}%',))

    results = [dict(row) for row in cursor.fetchall()]

    # Log the search action
    db.execute(
        "INSERT INTO audit_log (action, timestamp, details) VALUES (?, ?, ?)",
        ('user_search', time.time(), f'filter={username_filter},role={role_filter}')
    )
    db.commit()

    return jsonify({'users': results, 'count': len(results)})

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    db = get_db()
    user = db.execute(
        'SELECT id, username, email, role FROM users WHERE id = ?', (user_id,)
    ).fetchone()
    if user is None:
        return jsonify({'error': 'Not found'}), 404
    return jsonify(dict(user))

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
